package vista;
import modelo.Usuario;import javax.swing.*;import java.awt.*;
public class MenuPrincipal extends JFrame {private final Usuario usuario;public MenuPrincipal(Usuario u){super("Libroteca | Menú principal");usuario=u;setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(760,480);setLocationRelativeTo(null);JPanel root=new JPanel(new BorderLayout(15,15));root.setBorder(BorderFactory.createEmptyBorder(20,24,20,24));JLabel heading=new JLabel("Biblioteca Escolar · Bienvenido/a, "+u.getNombre()+" ("+u.getRol()+")");heading.setFont(heading.getFont().deriveFont(Font.BOLD,18f));root.add(heading,BorderLayout.NORTH);JPanel actions=new JPanel(new GridLayout(0,2,12,12));addButton(actions,"Gestión de libros",()->new LibrosFrame(usuario).setVisible(true));addButton(actions,"Préstamos y devoluciones",()->new PrestamosFrame(usuario).setVisible(true));if(u.esBibliotecario()){addButton(actions,"Reportes",()->new ReportesFrame().setVisible(true));addButton(actions,"Gestión de estudiantes",()->new EstudiantesFrame().setVisible(true));}root.add(actions,BorderLayout.CENTER);JButton salir=new JButton("Cerrar sesión");salir.addActionListener(e->{new LoginFrame().setVisible(true);dispose();});root.add(salir,BorderLayout.SOUTH);setContentPane(root);}private void addButton(JPanel p,String t,Runnable r){JButton b=new JButton(t);b.setFont(b.getFont().deriveFont(15f));b.addActionListener(e->r.run());p.add(b);}}
